contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 newLimit, uint256 newDifficulty) public payable {
        require(newLimit > 0);
        // Owner (this contract) sets the bet limit for arbitrary input
        c.AdjustBetAmounts(newLimit);
        c.AdjustDifficulty(newDifficulty);

        uint256 observedLimit = c.currentBetLimit();
        uint256 observedDifficulty = c.currentDifficulty();

        // Any wager with a wrong value must revert, since betLimit == newLimit
        bool wrongValueReverted;
        try c.wager{value: newLimit + 1}() { wrongValueReverted = false; }
        catch { wrongValueReverted = true; }

        assert(observedLimit == newLimit && observedDifficulty == newDifficulty && wrongValueReverted);
    }

    receive() external payable {}
}

