contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 newLimit, bool asOwner) public {
        uint256 beforeLimit = c.currentBetLimit();
        bool reverted;
        if (asOwner) {
            // InvMutTest is the deployer, hence the owner
            c.AdjustBetAmounts(newLimit);
            reverted = false;
        } else {
            // simulate a non-owner by checking from another context is not possible;
            // instead use owner path via try on a call that must succeed, and for
            // non-owner use delegate-less approach: we can only be msg.sender, so
            // treat asOwner==false via an external EOA is impossible in one tx.
            // Therefore: verify the owner rule generally and that a wrong-owner
            // path cannot be exercised by us; skip by using try on a fresh call.
            try c.AdjustBetAmounts(newLimit) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }
        uint256 afterLimit = c.currentBetLimit();
        if (reverted) {
            assert(afterLimit == beforeLimit);
        } else {
            assert(afterLimit == newLimit);
        }
    }
    receive() external payable {}
}

